export const faqGroups = groups.map(({rows,...group}) => ({...group,items:rows.trim().split("\n").map((line,index) => {
  const [question,answer,source] = line.split("|");
  if (!question || !answer || (source && !faqSources[source])) throw new Error(`Invalid FAQ: ${group.id}/${index + 1}`);
  return {id:`${group.id}-${String(index + 1).padStart(2,"0")}`,question,answer,source};
})}));
export const faqCount = faqGroups.reduce((sum,group) => sum + group.items.length,0);
